from pathlib import Path
class N:
 def __init__(self,d,p=0):
  self.d=d;self.p=p;start=p;t=d[p];p+=1;self.cls=t>>6;self.cons=bool(t&32);self.tag=t&31
  if self.tag==31:
   self.tag=0
   while True:
    b=d[p];p+=1;self.tag=self.tag*128+(b&127)
    if b<128:break
  self.lp=p;b=d[p];p+=1;self.ind=b==128
  if b>128:
   n=b&127;ln=int.from_bytes(d[p:p+n],'big');p+=n
  else:ln=b
  self.v=p;self.ch=[]
  if self.ind:
   while d[p:p+2]!=b'\0\0':
    c=N(d,p);self.ch.append(c);p=c.end
   self.ce=p;self.end=p+2
  else:
   self.ce=p+ln;self.end=self.ce
   if self.cons:
    while p<self.ce:
     c=N(d,p);self.ch.append(c);p=c.end
  self.val=d[self.v:self.ce];self.raw=d[self.p:self.end]
 def tree(self,path=()):
  yield path,self
  for i,c in enumerate(self.ch):yield from c.tree(path+(i,))
 def __repr__(self):return f'{self.p}: {self.cls}/{self.tag}{"C" if self.cons else "P"} len={len(self.val)}'
def length(n):return bytes([n]) if n<128 else bytes([128+(n.bit_length()+7)//8])+n.to_bytes((n.bit_length()+7)//8,'big')
if __name__=='__main__':
 for p in sorted(Path('/app/corpus').glob('*.der')):
