   if c.cls==0 and c.tag in (3,4) and c.cons:flags.append('STRING')
   if c.cls==0 and c.tag==2 and len(c.val)>1 and ((c.val[0]==0 and c.val[1]<128) or (c.val[0]==255 and c.val[1]>=128)):flags.append('INTEGER')
   if c.cls==0 and c.tag==17 and any(a.raw>=b.raw for a,b in zip(c.ch,c.ch[1:])):flags.append('SET_RAW')
   if c.cls==0 and c.tag==1 and c.val==b'\0':flags.append('FALSE')
   if c.cls==2 and c.tag==0 and len(c.ch)==1 and c.ch[0].tag==2 and int.from_bytes(c.ch[0].val,'big',signed=True)==0:flags.append('V1')
   if flags:print('.'.join(map(str,path)),c,','.join(flags))
  for cert in n.ch[1].ch[0].ch[3].ch:
   tbs=cert.ch[0]
   exts=next((x.ch[0].ch for x in tbs.ch if x.cls==2 and x.tag==3),[])
   for ext in exts:
    c=ext.ch[-1]
    print('EXT',c.p,c.val.hex())
